const $ = s => document.querySelector(s);
const escape = s => String(s ?? '').replace(/[&<>"']/g, x => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const formatDate = s => new Date(s).toLocaleString('zh-CN',{timeZone:'UTC',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false})+' UTC';
let data, page=1, filtered=[], saved=new Set();
try { saved=new Set(JSON.parse(localStorage.getItem('job-observatory-saved')||'[]').filter(x=>typeof x==='string')); } catch {}
const notify=text=>{const t=$('#toast');t.textContent=text;t.style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>t.style.display='none',2600)};
function route(){let name=location.hash.slice(1)||'overview';if(!['overview','jobs','method'].includes(name))name='overview';document.querySelectorAll('.page').forEach(el=>el.hidden=el.id!==name);document.querySelectorAll('[data-route]').forEach(el=>{el.classList.toggle('active',el.dataset.route===name);if(el.dataset.route===name)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current')});if($('#detail').open)$('#detail').close();}
function chooseSkill(skill){$('#skill').value=skill;$('#search').value='';$('#category').value='';$('#only-saved').checked=false;page=1;renderJobs();location.hash='jobs';}
function reset(){for(const id of ['search','category','skill'])$('#'+id).value='';$('#only-saved').checked=false;page=1;renderJobs();}
function renderJobs(){const q=$('#search').value.trim().toLowerCase(),category=$('#category').value,skill=$('#skill').value;
 filtered=data.jobs.filter(j=>(!category||j.categories.includes(category))&&(!skill||j.skills.some(s=>s.skill===skill))&&(!$('#only-saved').checked||saved.has(j.id))&&(!q||[j.title,j.company,j.location,...j.categories,...j.skills.map(s=>s.skill)].join(' ').toLowerCase().includes(q)));
 const pages=Math.max(1,Math.ceil(filtered.length/10));page=Math.min(Math.max(1,page),pages);
 $('#results-count').textContent=`${filtered.length} 条匹配 / ${data.jobs.length} 条本次样本`;
 $('#job-list').innerHTML=filtered.slice((page-1)*10,page*10).map(j=>`<article class="job"><div><div class="job-top"><span>${escape(j.company)}</span><span>${escape(j.categories.join(' · '))}</span></div><h3><button class="job-title" data-detail="${escape(j.id)}">${escape(j.title)}</button></h3><div class="job-meta">${escape(j.location)} · ${escape(j.level)} · ${escape(j.types.join(' / '))}</div><div class="job-meta">来源发布时间 ${escape(j.publishedAt)} · 非采集时间</div><div class="tags">${j.skills.length?j.skills.slice(0,8).map(s=>`<button class="tag" data-skill="${escape(s.skill)}">${escape(s.skill)}</button>`).join(''):'<span class="tag">词典未命中，不代表无需技能</span>'}${j.skills.length>8?`<button class="tag" data-detail="${j.id}">+${j.skills.length-8} 项</button>`:''}</div></div><div class="job-actions"><button class="save" data-save="${j.id}" aria-pressed="${saved.has(j.id)}">${saved.has(j.id)?'已标记 ✓':'标记观察 +'}</button><a class="source" href="${escape(j.url)}" target="_blank" rel="noopener noreferrer">来源 Jobicy ↗</a></div></article>`).join('');
 $('#empty').hidden=filtered.length>0;$('.pagination').hidden=filtered.length===0;$('#page-number').textContent=`${page} / ${pages}`;$('#prev').disabled=page===1;$('#next').disabled=page===pages;
}
function showDetail(id){const j=data.jobs.find(j=>j.id===id);if(!j)return;$('#detail-content').innerHTML=`<span class="eyebrow">SOURCE EVIDENCE / ${escape(j.id)}</span><h2 class="detail-title">${escape(j.title)}</h2><p class="detail-meta">${escape(j.company)} · ${escape(j.location)}<br>${escape(j.level)} · ${escape(j.types.join(' / '))}</p><div class="detail-warning">以下是标题或正文中出现的词，不区分必需、加分、否定或背景描述。阅读原岗位确认真实要求。</div><h3>技能词与原文命中</h3>${j.skills.length?j.skills.map(s=>`<div class="evidence-item"><strong>${escape(s.skill)}</strong><span>${escape(s.matched.join(' / '))}</span></div>`).join(''):'<p>当前词典未发现技能词，请直接阅读来源。</p>'}<p class="detail-small">采集时间 ${formatDate(data.observedAt)}<br>来源发布时间 ${escape(j.publishedAt)}<br>正文 SHA-256：${escape(j.descriptionHash)}<br>${escape(j.availability)}</p><a class="primary" href="${escape(j.url)}" target="_blank" rel="noopener noreferrer">阅读 Jobicy 原始岗位 <span>↗</span></a>`;$('#detail').showModal();}
function init(){const counts=new Map();data.jobs.forEach(j=>j.skills.forEach(s=>counts.set(s.skill,(counts.get(s.skill)||0)+1)));const ranking=[...counts.entries()].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]));
 $('#stamp').textContent=`最近采集 ${formatDate(data.observedAt)} · 来源 Jobicy`;
 const sync=data.syncInfo; const age=(Date.now()-Date.parse(data.observedAt))/3600000;const fresh=age>36?'已超过 36 小时，数据可能过期':'最近快照在 36 小时内';
 $('#sync-status').textContent=sync?`${fresh} · ${sync.schedule?.enabled?sync.schedule.description:'每日同步能力已就绪，定时任务尚未确认启用'}${sync.status==='failed'?' · 最近采集失败，旧快照已保留（'+sync.lastError+'）':''}${sync.status==='running'?' · 正在采集':''}`:`${fresh} · 本地基线预览`;
 $('#sync-status').classList.toggle('warning',age>36||sync?.status==='failed');
 $('#sync-detail').textContent=sync?`最近尝试：${sync.lastAttemptAt?formatDate(sync.lastAttemptAt):'尚无后台采集尝试'}；最近成功采集：${formatDate(sync.lastSuccessAt||data.observedAt)}。${sync.schedule?.enabled?'已记录调度：'+sync.schedule.description:'调度尚未确认启用。'}${sync.status==='failed'?' 最近失败：'+sync.lastError+'；数据未被覆盖。':''}`:'本地静态预览不代表后台调度已开启。';
 $('#stat-jobs').textContent=data.jobs.length;$('#stat-companies').textContent=new Set(data.jobs.map(j=>j.company)).size;$('#stat-skills').textContent=counts.size;$('#stat-history').textContent=data.history.length;
 $('#denominator').textContent=`分母：${data.jobs.length} 条岗位`;
 $('#skills-chart').innerHTML=ranking.slice(0,8).map(([skill,count])=>`<button class="bar-row" data-skill="${escape(skill)}" aria-label="${escape(skill)}，${count} 条岗位，查看证据"><span>${escape(skill)}</span><span class="bar"><i style="width:${count/data.jobs.length*100}%"></i></span><b>${count} 条</b></button>`).join('');
 // Pick a concrete technical learning experiment, clearly marked as a hypothesis, not a market verdict.
 const python=counts.get('Python')||0;
 $('#learning-content').innerHTML=python?`<p><b>Python 在 ${python}/${data.jobs.length} 条样本中被提到。</b>这值得进一步看它用于自动化、数据处理还是软件开发，不能仅凭频次决定转行。</p><p>先读 3 条岗位的完整要求，再做一个可复跑的数据清洗小项目。把实际遇到的能力缺口记下来。</p><a href="#jobs" data-learning="Python">查看 ${python} 条支持证据 →</a>`:`<p>先选一个与你目标相关的技能，打开至少 3 条原始岗位，区分必需条件和加分项，再决定一个小型练习。</p><a href="#jobs">从岗位证据开始 →</a>`;
 const categories=[...new Set(data.jobs.flatMap(j=>j.categories))].sort();$('#category').innerHTML='<option value="">全部类别</option>'+categories.map(c=>`<option>${escape(c)}</option>`).join('');$('#skill').innerHTML='<option value="">全部技能</option>'+ranking.map(([s,c])=>`<option value="${escape(s)}">${escape(s)} (${c})</option>`).join('');
 const categoryCounts=new Map();data.jobs.forEach(j=>j.categories.forEach(c=>categoryCounts.set(c,(categoryCounts.get(c)||0)+1)));const topCategory=[...categoryCounts.entries()].sort((a,b)=>b[1]-a[1])[0];
 $('#coverage').textContent=`本次 ${data.jobs.length} 条，${data.hasMore?'来源明确提示还有更多页，本版未采集':'响应未提示更多页'}。最大类别为 ${topCategory?.[0]||'未标注'}（${topCategory?.[1]||0} 条），样本结构会影响技能排序。`;
 $('#dictionary-note').textContent=`当前词典覆盖 ${data.dictionarySize} 个技术与通用技能标签，提取器版本：${data.extractorVersion}。`;
 $('#history-list').innerHTML=data.history.map((h,i)=>`<div class="history"><strong>${formatDate(h.observedAt)}</strong><div><p>${i===0?'基线快照':'追加快照'} · ${h.count} 条 · ${i===0?'未生成趋势结论':'同口径比较，变化不等于市场变化'}</p><code>响应 SHA-256 ${escape(h.responseSha256)}</code></div></div>`).join('')+'<div class="history"><strong>V0.1 / 产品决策</strong><div><p>真实 API 优先于抓取登录站点；选用允许研究工具的 Jobicy。保留必要元数据与技能词，避免全文复制。暂不比较薪酬，因为币种、周期与缺失值不同。</p></div></div>';
 if(data.comparison){$('#comparison').hidden=false;$('#comparison').textContent=data.comparison.comparable?`相邻同口径快照：首次看到 ${data.comparison.firstSeen.length} 条，内容变化 ${data.comparison.changed.length} 条，本批未出现 ${data.comparison.notInLatestSample.length} 条。未出现不代表岗位关闭；这些不是市场增减。`:data.comparison.reason+'。历史快照完整保留，不生成跨版本趋势。';}
 if(data.history.length>1){$('#baseline-title').textContent='已开始积累样本变化';$('#baseline-note').textContent=`保存了 ${data.history.length} 份快照。样本差异不代表市场增长或岗位关闭。`;}
 renderJobs();route();$('#loading').hidden=true;
}
document.addEventListener('click',e=>{const s=e.target.closest('[data-skill]'),d=e.target.closest('[data-detail]'),b=e.target.closest('[data-save]'),l=e.target.closest('[data-learning]');if(s)chooseSkill(s.dataset.skill);if(d)showDetail(d.dataset.detail);if(l){e.preventDefault();chooseSkill(l.dataset.learning)}if(b){const id=b.dataset.save;saved.has(id)?saved.delete(id):saved.add(id);try{localStorage.setItem('job-observatory-saved',JSON.stringify([...saved]));notify(saved.has(id)?'已标记，仅保存在当前浏览器':'已取消标记')}catch{notify('浏览器不允许保存；本次会话内仍可标记')}renderJobs();}});
$('#reset').onclick=reset;$('#empty-reset').onclick=reset;for(const id of ['search','category','skill','only-saved'])$('#'+id).addEventListener(id==='search'?'input':'change',()=>{page=1;renderJobs()});$('#prev').onclick=()=>{page--;renderJobs();$('#jobs').scrollIntoView({behavior:'smooth'})};$('#next').onclick=()=>{page++;renderJobs();$('#jobs').scrollIntoView({behavior:'smooth'})};$('.close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});window.addEventListener('hashchange',()=>{if(data){route();window.scrollTo(0,0)}});
try{let response=await fetch('api/data');if(!response.ok&&['localhost','127.0.0.1'].includes(location.hostname))response=await fetch('data.json');if(!response.ok)throw new Error('snapshot unavailable');data=await response.json();if(!Array.isArray(data.jobs)||!data.jobs.length)throw new Error('empty snapshot');init()}catch(e){$('#loading').hidden=true;$('#error').hidden=false;console.error('Snapshot load failed',e)}
